<?php $page_title='Orders';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$st=$_POST['status'];if(in_array($st,['pending','processing','shipped','delivered','cancelled'],true)){if($st==='cancelled'&&!isset($_POST['confirmed'])){flash('error','Cancellation requires confirmation.');}else{$pdo->prepare("UPDATE orders SET order_status=? WHERE id=?")->execute([$st,$id]);flash('success','Order status updated successfully.');}}header('Location: orders.php');exit;}$q=trim($_GET['q']??'');$st=$_GET['status']??'';$sort=$_GET['sort']??'newest';$where=[];$params=[];if($q){$where[]="(CAST(o.id AS CHAR) LIKE ? OR o.customer_name LIKE ? OR o.customer_email LIKE ?)";$params=["%$q%","%$q%","%$q%"];}if(in_array($st,['pending','processing','shipped','delivered','cancelled'],true)){$where[]="o.order_status=?";$params[]=$st;}$order=['newest'=>'o.created_at DESC','oldest'=>'o.created_at ASC','high'=>'o.total DESC','low'=>'o.total ASC'][$sort]??'o.created_at DESC';$sql="SELECT o.*,COUNT(oi.id) item_count,COALESCE(SUM(oi.quantity),0) qty FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id ".($where?'WHERE '.implode(' AND ',$where):'')." GROUP BY o.id ORDER BY $order LIMIT 100";$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();?>
<div class="page-head"><div><h1>Orders</h1><p>Every customer order, stored directly in MySQL.</p></div></div><div class="panel"><form class="filters"><input class="input" name="q" placeholder="Order ID, customer or email" value="<?=e($q)?>"><select name="status"><option value="">All statuses</option><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $x):?><option value="<?=$x?>" <?=$st===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach;?></select><select name="sort"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="high">Highest amount</option><option value="low">Lowest amount</option></select><button class="btn">Filter</button></form><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Date</th><th>Items</th><th>Subtotal</th><th>Discount</th><th>Shipping</th><th>Tax</th><th>Total</th><th>Payment</th><th>Status</th><th>Action</th></tr><?php foreach($orders as $o):?><tr><td><strong>#<?=$o['id']?></strong></td><td><?=e($o['customer_name'])?><br><small><?=e($o['customer_email'])?></small><br><small><?=e($o['phone'])?></small></td><td><?=date('M d, Y H:i',strtotime($o['created_at']))?></td><td><?=$o['qty']?> / <?=$o['item_count']?> products</td><td><?=money((float)$o['subtotal'])?></td><td><?=money((float)$o['discount'])?></td><td><?=money((float)$o['shipping'])?></td><td><?=money((float)$o['tax'])?></td><td><strong><?=money((float)$o['total'])?></strong></td><td><?=e(strtoupper($o['payment_method']))?><br><small><?=e($o['payment_status'])?></small></td><td><span class="badge <?=e($o['order_status'])?>"><?=e(ucfirst($o['order_status']))?></span></td><td><a class="btn light" href="order-details.php?id=<?=$o['id']?>">View</a><form method="post" style="margin-top:5px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" onchange="if(this.value==='cancelled'&&!confirm('Are you sure you want to cancel this order?')){this.value='<?=$o['order_status']?>';return;}this.form.submit()"><?php foreach(['pending','processing','shipped','delivered','cancelled'] as $x):?><option <?=$x===$o['order_status']?'selected':''?> value="<?=$x?>"><?=ucfirst($x)?></option><?php endforeach;?></select><input type="hidden" name="confirmed" value="1"></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
